import os, re, json
import glob

# Load any previous session data first
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
session_jsonl = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
if os.path.exists(session_jsonl):
    content = open(session_jsonl).read().replace('\n', '\n')
else:
    content = ''

# Extract any demo pairs, test inputs, output grids
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in content[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Available grids:", sorted(G.keys()))
for k, grid in G.items():
    print(f"{k}: {len(grid)}x{len(grid[0])}")
